SELECT AVG(tax_amount) AS average_tax_amount
FROM build4all_research.orders
WHERE status = 'cancelled';

SELECT AVG(tax_amount) AS average_tax_amount
FROM build4all_research.orders
WHERE status = 'cancelled';

SELECT AVG(tax_amount) AS average_tax_amount
FROM build4all_research.orders
WHERE status = 'completed';

SELECT AVG(tax_amount) AS average_tax_amount
FROM build4all_research.orders
WHERE status = 'completed';

SELECT AVG(tax_amount) AS average_tax_amount
