SELECT COUNT(*) AS total_payments
FROM build4all_research.payments
WHERE payment_method = 'cash_on_delivery';

SELECT AVG(price) AS average_price
FROM build4all_research.products
WHERE status = 'active';

SELECT AVG(price) AS average_catalog_price
FROM build4all_research.products
WHERE status = 'active';

SELECT product_id, name, price, sale_price, status 
FROM build4all_research.products 
WHERE status = 'active';

SELECT SUM(sale_price * stock) AS inventory_value
FROM build4all_research.products
WHERE status = 'active' AND sale_price IS NOT NULL;

SELECT SUM(CASE WHEN p.sale_price IS NOT NULL THEN p.sale_price ELSE p.price END * p.stock) AS total_stock_value
FROM build4all_research.products p
WHERE p.status = 'active';

SELECT COUNT(DISTINCT products.category_id)
FROM products
WHERE products.status = 'active';

SELECT COUNT(DISTINCT products.category_id)
FROM products
WHERE products.status = 'active';

SELECT AVG(price) AS average_price
FROM build4all_research.products
WHERE status = 'discontinued';

SELECT AVG(price) AS average_catalog_price
FROM build4all_research.products
WHERE status = 'discontinued';

SELECT product_id, name, price, sale_price, status 
FROM build4all_research.products 
WHERE status = 'discontinued';

SELECT SUM(stock * COALESCE(sale_price, price)) AS inventory_value
FROM build4all_research.products
WHERE status = 'discontinued';

SELECT COUNT(DISTINCT p.category_id)
FROM build4all_research.products p
WHERE p.status = 'discontinued';

SELECT COUNT(DISTINCT products.category_id)
FROM products
WHERE products.status = 'discontinued';

SELECT AVG(price) AS average_list_price
