SELECT SUM(CASE WHEN p.status = 'out_of_stock' THEN COALESCE(p.sale_price, 0) * p.stock ELSE 0 END) AS total_stock_value_with_sale_price
FROM build4all_research.products p
WHERE p.status = 'out_of_stock';

